[BusinessEvents(classStr(METItemPackChangeCompletedBusinessEventContract),
    "@MET:ItemPackChangeCompletedBusinessEventName",
    "@MET:ItemPackChangeCompletedBusinessEventDescHelptext",
    ModuleAxapta::Customer)]
internal final class METItemPackChangeCompletedBusinessEvent
{
    private METTempItemPackChg tempItemPackChg;
    private ItemId itemId;
    private InventSiteId inventSiteId;

}

